<?php require 'config.php'; $cart=$_SESSION['cart']??[]; if(isset($_GET['remove'])){unset($cart[(int)$_GET['remove']]);$_SESSION['cart']=$cart;header('Location: cart.php');exit;} $_SESSION['cart']=$cart;$items=[];$total=0;
if($cart){$ids=implode(',',array_map('intval',array_keys($cart)));$r=$conn->query("SELECT * FROM products WHERE product_id IN ($ids)");while($p=$r->fetch_assoc()){$p['qty']=$cart[$p['product_id']];$p['line']=$p['qty']*$p['price'];$total+=$p['line'];$items[]=$p;}}
?>
