<header class="navbar"><div class="container navin"><a class="brand" href="index.php"><img src="assets/images/logo.svg" alt="LSD Cricket"></a><button class="iconbtn mobile-toggle">☰</button><nav class="navlinks"><a href="index.php">Home</a><a href="shop.php">Shop</a><a href="shop.php?category=hard">Hard Cricket</a><a href="shop.php?category=soft">Soft Cricket</a></nav><div class="nav-actions"><a class="iconbtn" href="signin.php">👤 Sign In</a><a class="iconbtn" href="cart.php">🛒 <span class="cartbadge" id="cartCount"><?=cart_count()?></span></a></div></div></header>
<main class="page"><div class="container"><div class="eyebrow">YOUR BAG</div><h1>Shopping Cart</h1><?php if(!$items):?><div class="panel empty-cart"><div class="empty-icon">🛒</div><h3>Your cart is empty</h3><p class="muted">Find your next piece of cricket gear.</p><a class="btn btn-primary" href="shop.php">Start Shopping</a></div><?php else:?><div class="cart-layout"><div class="panel" id="cartItems"><?php foreach($items as $p):?><div class="cart-item" data-item-id="<?=$p['product_id']?>"><img src="<?=e($p['image'])?>" alt=""><div class="cart-info"><strong><?=e($p['name'])?></strong><p class="muted"><?=money($p['price'])?></p><button class="text-btn cart-remove" data-id="<?=$p['product_id']?>">Remove</button></div><div class="qty-control"><button class="qty-btn" data-delta="-1">−</button><input class="input cart-qty" type="number" min="1" max="<?=e($p['stock'])?>" value="<?=$p['qty']?>"><button class="qty-btn" data-delta="1">+</button></div><strong class="line-total"><?=money($p['line'])?></strong></div><?php endforeach;?></div><aside class="panel summary-sticky"><h3>Order Summary</h3><div class="summary-row"><span>Subtotal</span><b id="cartSubtotal"><?=money($total)?></b></div><div class="summary-row"><span>Delivery</span><span class="muted">Calculated at checkout</span></div><div class="total"><div class="summary-row"><span>Total</span><span id="cartTotal"><?=money($total)?></span></div></div><a class="btn btn-primary" style="width:100%;margin-top:12px" href="checkout.php">Secure Checkout →</a><p class="secure-note">🔒 Safe & secure checkout</p></aside></div><?php endif;?></div></main><script src="assets/js/app.js"></script></body></html>